            parsed = json.loads(raw)
            if isinstance(parsed, list):
                return [str(p) for p in parsed]
        except Exception:
            pass
    return [raw]


def _pdf_text(path):
    doc = fitz.open(path)
    try:
        return '\n'.join((page.get_text() or '') for page in doc).strip()
    finally:
        doc.close()


def _ocr_pdf(path, file_name):
    with open(path, 'rb') as f:
        resp = requests.post(
            OCR_URL,
            files=[('files', (file_name, f, 'application/pdf'))],
            data={'return_content_list': 'true', 'backend': 'pipeline'},
            timeout=900)
