        if truncated:
            notes.append('报告过长，已截断至 {} 字符，尾部内容未纳入分析'.format(MAX_REPORT_CHARS))
        return {'report_text': report_text, 'parse_note': '；'.join(n for n in notes if n), 'error': ''}
