import csv
import json
import os

import fitz
import requests
from bisheng.core.cache.utils import file_download

OCR_URL = 'http://172.19.0.3:8010/file_parse'
MIN_TEXT_CHARS = 300
MAX_TEXT_CHARS = 60000

# 引擎 CodeParser 只注入 ast.Constant 模块级变量，tuple/list 必须写成字符串常量
PDF_EXTS = '.pdf'
EXCEL_EXTS = '.xlsx,.xlsm'
XLS_EXTS = '.xls'
CSV_EXTS = '.csv'
IMAGE_EXTS = '.png,.jpg,.jpeg,.bmp,.tif,.tiff,.webp'


def _parse_paths(paths):
    if not paths:
        return []
    if isinstance(paths, list):
        return [str(p) for p in paths]
    raw = str(paths)
    if raw.startswith('['):
        try:
            parsed = json.loads(raw)
            if isinstance(parsed, list):
                return [str(p) for p in parsed]
        except Exception:
            pass
    return [raw]


def _ext(path):
    return os.path.splitext(path)[1].lower()


def _pdf_text(path):
    doc = fitz.open(path)
    try:
        return '\n'.join((page.get_text() or '') for page in doc).strip()
    finally:
        doc.close()


def _ocr_file(path, file_name, mime):
    with open(path, 'rb') as f:
        resp = requests.post(
            OCR_URL,
            files=[('files', (file_name, f, mime))],
            data={'return_content_list': 'true', 'backend': 'pipeline'},
            timeout=900)
    resp.raise_for_status()
    payload = resp.json()
    results = payload.get('results') or {}
    text = ''
    for res in results.values():
        content_list = res.get('content_list') or []
        if isinstance(content_list, str):
            try:
                content_list = json.loads(content_list)
            except Exception:
                content_list = []
        for block in content_list:
            if isinstance(block, dict):
                text += (block.get('text') or '') + '\n'
    return text.strip()


def _xlsx_text(path):
    import openpyxl
    wb = openpyxl.load_workbook(path, data_only=True, read_only=True)
    parts = []
    for ws in wb.worksheets:
        parts.append('【工作表：{}】'.format(ws.title))
        for row in ws.iter_rows(values_only=True):
            cells = ['' if c is None else str(c).strip() for c in row]
            if any(cells):
                parts.append(' | '.join(cells))
    return '\n'.join(parts)


def _xls_text(path):
    import xlrd
    wb = xlrd.open_workbook(path)
    parts = []
    for ws in wb.sheets():
        parts.append('【工作表：{}】'.format(ws.name))
        for r in range(ws.nrows):
            cells = [str(ws.cell_value(r, c)).strip() for c in range(ws.ncols)]
            if any(cells):
                parts.append(' | '.join(cells))
    return '\n'.join(parts)


def _csv_text(path):
    for enc in ('utf-8-sig', 'gbk', 'utf-8'):
        try:
            with open(path, encoding=enc, newline='') as f:
                rows = [row for row in csv.reader(f) if any(row)]
            return '\n'.join(' | '.join(row) for row in rows)
        except UnicodeDecodeError:
            continue
    return ''


def main(bank_flow_path: list) -> dict:
    try:
        paths = _parse_paths(bank_flow_path)
        if not paths:
            return {'flow_text': '', 'parse_note': '',
                    'error': '未收到流水文件，请在上一步表单中上传银行流水（PDF/Excel/图片，可多份）。'}
        parts = []
        notes = []
        for url in paths:
            local_file, file_name = file_download(url)
            ext = _ext(local_file)
            text = ''
            if ext in PDF_EXTS.split(','):
                text = _pdf_text(local_file)
                if len(text) < MIN_TEXT_CHARS:
                    notes.append('{} 为扫描件，已走 OCR 解析'.format(file_name))
                    text = _ocr_file(local_file, file_name, 'application/pdf')
                else:
                    notes.append('{} 为文本版 PDF，直接读取'.format(file_name))
            elif ext in EXCEL_EXTS.split(','):
                notes.append('{} 为 Excel 表格，直接读取'.format(file_name))
                text = _xlsx_text(local_file)
            elif ext in XLS_EXTS.split(','):
                notes.append('{} 为 Excel 表格，直接读取'.format(file_name))
                text = _xls_text(local_file)
            elif ext in CSV_EXTS.split(','):
                notes.append('{} 为 CSV，直接读取'.format(file_name))
                text = _csv_text(local_file)
            elif ext in IMAGE_EXTS.split(','):
                notes.append('{} 为图片，已走 OCR 解析'.format(file_name))
                text = _ocr_file(local_file, file_name, 'image/jpeg')
            else:
                # 未知类型：先尝试按文本直接读取，失败则走 OCR
                try:
                    with open(local_file, encoding='utf-8', errors='ignore') as f:
                        text = f.read().strip()
                    notes.append('{} 按文本直接读取'.format(file_name))
                except Exception:
                    notes.append('{} 无法识别类型，尝试 OCR 解析'.format(file_name))
                    text = _ocr_file(local_file, file_name, 'application/octet-stream')
            if not text:
                return {'flow_text': '', 'parse_note': '；'.join(notes),
                        'error': '文件 {} 无法提取内容（OCR 服务不可用或文件损坏），请上传清晰的文本版流水'.format(file_name)}
            parts.append(text)
        flow_text = '\n\n'.join(parts)
        truncated = len(flow_text) > MAX_TEXT_CHARS
        if truncated:
            flow_text = flow_text[:MAX_TEXT_CHARS]
        if len(parts) > 1:
            notes.append('多文件已合并分析')
        if truncated:
            notes.append('流水过长，已截断至 {} 字符，尾部内容未纳入分析'.format(MAX_TEXT_CHARS))
        return {'flow_text': flow_text, 'parse_note': '；'.join(n for n in notes if n), 'error': ''}
    except Exception as exc:
        return {'flow_text': '', 'parse_note': '', 'error': '解析失败：{}'.format(exc)}

