import json


def _num(v):
    try:
        f = float(v)
        return f
    except (TypeError, ValueError):
        return None


def _pct(a, b):
    if a is None or b is None or b == 0:
        return None
    return round(a / b * 100, 2)


def _ratio(a, b):
    if a is None or b is None or b == 0:
        return None
    return round(a / b, 2)


def _trend(cur, prev):
    if cur is None or prev is None or prev == 0:
        return None
    return round((cur - prev) / abs(prev) * 100, 2)


def main(extraction: str) -> dict:
    try:
        text = (extraction or '').strip()
        start = text.find('{')
        end = text.rfind('}')
        if start < 0 or end <= start:
            return {'indicators': '', 'error': '数据提取结果不是有效 JSON，无法计算财务指标'}
        data = json.loads(text[start:end + 1])
        if isinstance(data, dict) and data.get('error'):
            return {'indicators': '', 'error': '数据提取失败：{}'.format(data['error'])}
        bs = data.get('balance_sheet') or []
        inc = data.get('income_statement') or []
        cf = data.get('cash_flow') or []
        unit = data.get('unit') or ''
        if not bs:
            return {'indicators': '', 'error': '未提取到资产负债表数据，无法计算财务指标'}
        # LLM 输出的期数顺序不可信 — 统一按 period 升序（旧→新），趋势计算依赖该顺序
        bs = sorted([r for r in bs if isinstance(r, dict) and r.get('period')], key=lambda r: str(r.get('period')))
        inc = sorted([r for r in inc if isinstance(r, dict) and r.get('period')], key=lambda r: str(r.get('period')))
        cf = sorted([r for r in cf if isinstance(r, dict) and r.get('period')], key=lambda r: str(r.get('period')))

        def by_period(rows, key):
            return {r.get('period'): r.get(key) for r in rows if isinstance(r, dict) and r.get('period')}

        lines = []
        lines.append('【指标计算】单位：{}'.format(unit if unit else '原表'))
        rows = []
        for period in [r.get('period') for r in bs]:
            if not period:
                continue
            ta = _num(by_period(bs, 'total_assets').get(period))
            tl = _num(by_period(bs, 'total_liabilities').get(period))
            ca = _num(by_period(bs, 'current_assets').get(period))
            cl = _num(by_period(bs, 'current_liabilities').get(period))
            inv = _num(by_period(bs, 'inventory').get(period))
            rev = _num(by_period(inc, 'revenue').get(period))
            np_ = _num(by_period(inc, 'net_profit').get(period))
            gp = _num(by_period(inc, 'gross_profit').get(period))
            ocf = _num(by_period(cf, 'operating_cash_flow').get(period))
            rows.append({
                'period': period,
                'debt_ratio': _pct(tl, ta),
                'current_ratio': _ratio(ca, cl),
                'quick_ratio': _ratio((ca - inv) if ca is not None and inv is not None else None, cl),
                'net_margin': _pct(np_, rev),
                'gross_margin': _pct(gp, rev),
                'ocf_to_revenue': _ratio(ocf, rev),
                'ocf_to_profit': _ratio(ocf, np_) if np_ is not None and np_ > 0 else None,
            })
        if not rows:
            return {'indicators': '', 'error': '报表期数缺失，无法计算财务指标'}

        labels = [('资产负债率', 'debt_ratio', '%'), ('流动比率', 'current_ratio', ''),
                  ('速动比率', 'quick_ratio', ''), ('净利率', 'net_margin', '%'),
                  ('毛利率', 'gross_margin', '%'), ('收入现金保障倍数', 'ocf_to_revenue', ''),
                  ('利润现金保障倍数', 'ocf_to_profit', '')]
        for label, key, suffix in labels:
            vals = [(r['period'], r[key]) for r in rows]
            cells = ' | '.join('{}：{}'.format(p, 'N/A' if v is None else '{}{}'.format(v, suffix)) for p, v in vals)
            trend = ''
            if len(vals) >= 2 and vals[-1][1] is not None and vals[-2][1] is not None:
                chg = _trend(vals[-1][1], vals[-2][1])
                trend = '，较上期{}{}%'.format('+' if chg >= 0 else '', chg)
            lines.append('- {}：{}{}'.format(label, cells, trend))
        if len(rows) >= 2:
            last, prev = rows[-1], rows[-2]
            chg_rev = _trend(_num(by_period(inc, 'revenue').get(last['period'])),
                             _num(by_period(inc, 'revenue').get(prev['period'])))
            chg_np = _trend(_num(by_period(inc, 'net_profit').get(last['period'])),
                            _num(by_period(inc, 'net_profit').get(prev['period'])))
            chg_ar = _trend(_num(by_period(bs, 'accounts_receivable').get(last['period'])),
                            _num(by_period(bs, 'accounts_receivable').get(prev['period'])))
            chg_inv = _trend(_num(by_period(bs, 'inventory').get(last['period'])),
                             _num(by_period(bs, 'inventory').get(prev['period'])))
            lines.append('- 营收同比：{}%；净利润同比：{}%；应收账款同比：{}%；存货同比：{}%'.format(
                'N/A' if chg_rev is None else chg_rev, 'N/A' if chg_np is None else chg_np,
                'N/A' if chg_ar is None else chg_ar, 'N/A' if chg_inv is None else chg_inv))
        return {'indicators': '\\n'.join(lines), 'error': ''}
    except Exception as exc:
        return {'indicators': '', 'error': '指标计算失败：{}'.format(exc)}

