        return f
    except (TypeError, ValueError):
        return None


def _pct(a, b):
    if a is None or b is None or b == 0:
        return None
    return round(a / b * 100, 2)


def _ratio(a, b):
    if a is None or b is None or b == 0:
        return None
    return round(a / b, 2)


def _trend(cur, prev):
    if cur is None or prev is None or prev == 0:
        return None
    return round((cur - prev) / abs(prev) * 100, 2)


def main(extraction: str) -> dict:
    try:
        text = (extraction or '').strip()
        start = text.find('{')
        end = text.rfind('}')
        if start < 0 or end <= start:
            return {'indicators': '', 'error': '数据提取结果不是有效 JSON，无法计算财务指标'}
        data = json.loads(text[start:end + 1])
        if isinstance(data, dict) and data.get('error'):
            return {'indicators': '', 'error': '数据提取失败：{}'.format(data['error'])}
        bs = data.get('balance_sheet') or []
        inc = data.get('income_statement') or []
        cf = data.get('cash_flow') or []
        unit = data.get('unit') or ''
        if not bs:
