            lines.append('- 营收同比：{}%；净利润同比：{}%；应收账款同比：{}%；存货同比：{}%'.format(
                'N/A' if chg_rev is None else chg_rev, 'N/A' if chg_np is None else chg_np,
                'N/A' if chg_ar is None else chg_ar, 'N/A' if chg_inv is None else chg_inv))
